const express = require('express');
const session = require('express-session');
const crypto = require('node:crypto');
const { promisify } = require('node:util');

const scrypt = promisify(crypto.scrypt);

// --- password hashing (stdlib scrypt, random salt per password) ---

async function hashPassword(password) {
  const salt = crypto.randomBytes(16);
  const key = await scrypt(password, salt, 64);
  return `${salt.toString('hex')}:${key.toString('hex')}`;
}

async function verifyPassword(password, stored) {
  const [salt, key] = stored.split(':').map((h) => Buffer.from(h, 'hex'));
  return crypto.timingSafeEqual(key, await scrypt(password, salt, 64));
}

// Verified against when the user doesn't exist, so response time doesn't reveal which usernames are real.
const dummyHash = hashPassword(crypto.randomUUID());

// --- rate limiting of failed attempts ---

const WINDOW_MS = 15 * 60 * 1000;
const MAX_PER_USER = 5; // stops guessing one account from many IPs
const MAX_PER_IP = 50; // stops one IP spraying many accounts

// ponytail: in-memory, single process. Move to Redis (INCR + EXPIRE) when running more than one instance.
const attempts = new Map(); // key -> { count, resetAt }

function bump(key) {
  const now = Date.now();
  let entry = attempts.get(key);
  if (!entry || entry.resetAt <= now) {
    entry = { count: 0, resetAt: now + WINDOW_MS };
    attempts.set(key, entry);
  }
  entry.count++;
  return entry;
}

// Drop expired entries so attacker-chosen usernames can't grow the map forever.
setInterval(() => {
  const now = Date.now();
  for (const [key, entry] of attempts) if (entry.resetAt <= now) attempts.delete(key);
}, WINDOW_MS).unref();

// --- app ---

// ponytail: in-memory users. Swap for a DB table with a unique index on username.
const users = new Map(); // username -> { hash }

const app = express();
// Behind a reverse proxy, set `app.set('trust proxy', 1)` or req.ip is the proxy and secure cookies won't be sent.
app.use(express.json());
app.use(
  session({
    name: 'sid',
    // A random fallback secret logs everyone out on restart; set SESSION_SECRET in production.
    secret: process.env.SESSION_SECRET || crypto.randomBytes(32).toString('hex'),
    resave: false,
    saveUninitialized: false,
    // ponytail: default MemoryStore leaks and is per-process. Use connect-redis / connect-pg-simple in production.
    cookie: {
      httpOnly: true,
      sameSite: 'lax',
      secure: process.env.NODE_ENV === 'production',
      maxAge: 24 * 60 * 60 * 1000,
    },
  })
);

function credentials(body) {
  const { username, password } = body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string') return null;
  if (username.length < 1 || username.length > 64) return null;
  if (password.length < 8 || password.length > 1024) return null;
  return { username: username.toLowerCase(), password };
}

app.post('/register', async (req, res) => {
  const creds = credentials(req.body);
  if (!creds) return res.status(400).json({ error: 'username (1-64 chars) and password (8-1024 chars) required' });
  if (users.has(creds.username)) return res.status(409).json({ error: 'username taken' });
  users.set(creds.username, { hash: await hashPassword(creds.password) });
  res.status(201).json({ ok: true });
});

app.post('/login', async (req, res, next) => {
  const creds = credentials(req.body);
  if (!creds) return res.status(400).json({ error: 'invalid username or password format' });

  // Count the attempt before verifying, so parallel requests can't all slip under the limit.
  const userKey = `user:${creds.username}`;
  const byUser = bump(userKey);
  const byIp = bump(`ip:${req.ip}`);
  if (byUser.count > MAX_PER_USER || byIp.count > MAX_PER_IP) {
    const resetAt = byUser.count > MAX_PER_USER ? byUser.resetAt : byIp.resetAt;
    res.set('Retry-After', String(Math.ceil((resetAt - Date.now()) / 1000)));
    return res.status(429).json({ error: 'too many failed attempts, try again later' });
  }

  const user = users.get(creds.username);
  const ok = await verifyPassword(creds.password, user?.hash ?? (await dummyHash));
  if (!user || !ok) return res.status(401).json({ error: 'invalid username or password' });

  // Success isn't a failed attempt: undo the count.
  attempts.delete(userKey);
  byIp.count--;

  // New session id on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.username = creds.username;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid').json({ ok: true });
  });
});

function requireLogin(req, res, next) {
  if (!req.session.username) return res.status(401).json({ error: 'not logged in' });
  next();
}

app.get('/me', requireLogin, (req, res) => res.json({ username: req.session.username }));

if (require.main === module) {
  const port = process.env.PORT || 3000;
  app.listen(port, () => console.log(`listening on :${port}`));
}

module.exports = app;

const test = require('node:test');
const assert = require('node:assert');
const app = require('./app');

test('login flow, sessions, and lockout', async (t) => {
  const server = app.listen(0);
  t.after(() => server.close());
  const base = `http://localhost:${server.address().port}`;
  const post = (path, body, cookie) =>
    fetch(base + path, {
      method: 'POST',
      headers: { 'content-type': 'application/json', ...(cookie && { cookie }) },
      body: JSON.stringify(body),
    });

  const alice = { username: 'alice', password: 'correct horse' };
  assert.equal((await post('/register', alice)).status, 201);
  assert.equal((await post('/register', alice)).status, 409);
  assert.equal((await post('/register', { username: 'bob', password: 'short' })).status, 400);

  // no session -> no access
  assert.equal((await fetch(base + '/me')).status, 401);

  // good login -> session cookie works
  const login = await post('/login', alice);
  assert.equal(login.status, 200);
  const cookie = login.headers.get('set-cookie').split(';')[0];
  const me = await fetch(base + '/me', { headers: { cookie } });
  assert.deepEqual(await me.json(), { username: 'alice' });

  // logout kills the session
  assert.equal((await post('/logout', {}, cookie)).status, 200);
  assert.equal((await fetch(base + '/me', { headers: { cookie } })).status, 401);

  // unknown user looks the same as a wrong password
  assert.equal((await post('/login', { username: 'nobody', password: 'whatever1' })).status, 401);

  // 5 failures allowed, then locked out even with the right password
  const wrong = { username: 'alice', password: 'wrong password' };
  for (let i = 0; i < 5; i++) assert.equal((await post('/login', wrong)).status, 401);
  const locked = await post('/login', alice);
  assert.equal(locked.status, 429);
  assert.ok(Number(locked.headers.get('retry-after')) > 0);
});

